C = dict(id='GL-10', title='Cloud Migration as a Service', group='Digital and Technology', level=5,
 summary='Plan and run a safe move of one small business workload to cloud services, with cost, security and rollback decided before the move.',
 outcomes=['Explain cloud models, shared responsibility and when moving is not wise.', 'Inventory an existing workload and its dependencies.', 'Analyse cost, risk and downtime of two migration options.', 'Create a migration plan, test plan and rollback plan.', 'Evaluate the result after cut-over against agreed measures.'],
 task='Plan and complete a trial migration of one small workload (for example a website, shared files or a small app) to a cloud service, with a rollback.',
 cond='A small real or practice workload, a free or trial cloud account, a spreadsheet, a mentor with operations experience and a peer circle. About 12 weeks part-time.',
 std='Inventory complete; cost compared over 12 months; backup restored once as a test; cut-over done in the agreed window; user complaints within the agreed limit; rollback written.',
 who='IT staff, small-business owners, support engineers, college learners.', req='Basic computer and network knowledge.',
 safety='Use practice data or data you own. Never copy customer data to a trial account. Never store passwords or keys in documents.',
 mods=[
 ('Cloud models and shared responsibility', 'Know what you rent and what you must still protect.', ['Models: infrastructure, platform and software as a service.', 'The provider secures the building and hardware; you secure accounts, data and settings.', 'Public, private and mixed (hybrid) clouds.', 'When not to move: tight latency, special rules, tiny savings.'], 'A shop moves email to a software service: the provider patches servers, but the shop still must set strong sign-in and remove leavers.', 'Draw a responsibility table: provider versus you for five items.', 'Table is correct for each model.'),
 ('Inventory and dependencies', 'You cannot move what you have not listed.', ['List servers, apps, data size, users, licences and links to other systems.', 'Mark what must run together.', 'Find hidden items: scheduled jobs, printers, old shares.', 'Record owner and business importance.'], 'A web shop depends on a payment link, an email sender and a nightly stock file. Missing the last would break orders.', 'Build an inventory of at least 8 items with owners.', 'Dependencies drawn and checked with the owner.'),
 ('Choose the approach', 'Lift as-is, tweak, or rebuild: each has cost and risk.', ['Rehost (as-is) is quick; replatform (small change) saves more; rebuild costs most.', 'Compare on cost, time, risk and skill needed.', 'Pick by business need, not by fashion.', 'Decide a move order: low risk first.'], 'Option A: rehost, 2 weeks, risk low, saving 10%. Option B: rebuild, 3 months, saving 35%. For a small firm Option A first.', 'Score two options on a one-to-five table.', 'Choice backed by scores and a reason.'),
 ('Cost model', 'Cloud bills surprise people who skip the sums.', ['Count compute, storage, data out, support and backups.', 'Use the provider\'s free calculator, then add 20% margin.', 'Compare with current costs over 12 months, including staff time.', 'Set budget alerts.'], 'Current: 400 per month. Cloud: 220 compute + 60 storage + 30 backup = 310; plus 20% margin = 372. Saving 28 per month, 336 a year (state currency).', 'Build a 12-month cost table.', 'All cost lines shown with currency; margin included.'),
 ('Security and data', 'Move the data safely and keep it private.', ['Strong sign-in with a second step; least access.', 'Encrypt data in transit and at rest.', 'Know where data is stored; follow local data law.', 'Log who did what.'], 'Staff accounts: 12. Admin rights needed by 2. Remove admin from 10 and turn on the second step for all 12.', 'Write a security checklist and tick it for your workload.', 'Checklist complete; one gap fixed.'),
 ('Test, back up and rehearse', 'A test move shows problems when they are cheap.', ['Copy a small slice first.', 'Restore a backup once to prove it works.', 'Time the move: size divided by speed.', 'Write the cut-over steps minute by minute.'], '200 GB over 20 MB/s is 10,000 seconds, about 2.8 hours; plan a 4-hour window.', 'Run a trial move and a restore test.', 'Restore works; time measured.'),
 ('Cut-over and rollback', 'Move in a quiet window with a way back.', ['Tell users in advance.', 'Freeze changes, move, test, switch.', 'Decide a go or no-go point; roll back if tests fail.', 'Keep the old system for an agreed period.'], 'At 1 hour 45 minutes login fails for 5 of 12 users; the no-go rule says roll back at 2 hours; fix found, continue.', 'Write cut-over and rollback plans.', 'Plans have owners, times and go or no-go rules.'),
 ('Measure and hand over', 'Prove the move worked and teach the owner.', ['Compare speed, cost, complaints and downtime with goals.', 'Update the inventory and costs.', 'Train users and write a one-page guide.', 'Plan 90 days of improvements.'], 'Downtime 1.5 hours against 4 allowed; complaints 2 against 5 allowed; cost 7% lower.', 'Write a results page and a 90-day plan.', 'Results compare to targets with numbers.')],
 quiz=[('What does shared responsibility mean?', 'The provider secures the platform; you secure accounts, data and settings.'), ('Why take an inventory first?', 'You cannot plan or price what you have not listed.'), ('Name three migration approaches.', 'Rehost, replatform and rebuild.'), ('What costs hide in cloud bills?', 'Data out, support, backups and extra storage.'), ('Why test a restore?', 'A backup you cannot restore is not a backup.'), ('How do you estimate transfer time?', 'Data size divided by speed.'), ('What is a go or no-go point?', 'A time at which you decide to continue or roll back.'), ('Why keep the old system a while?', 'It gives a safe way back if problems appear late.'), ('What protects accounts best?', 'Strong sign-in with a second step and least access.'), ('What proves success?', 'Measured results against agreed goals.')],
 rubric=[('Inventory', 'All items and owners listed', 'Hidden items found and fixed'), ('Cost and options', 'Two options scored; 12-month costs', 'Sensitivity checked with a margin'), ('Security', 'Checklist complete', 'Gaps closed and logged'), ('Rehearsal and cut-over', 'Restore proven; plan timed', 'Cut-over inside window'), ('Results', 'Measured against goals', 'Improvements planned with dates')],
 jobs=[('Cloud support technician', 'Runs migrations and day-to-day support'), ('Managed service assistant', 'Looks after small clients\' systems'), ('IT consultant for small firms', 'Plans and prices moves'), ('Operations analyst', 'Tracks cost and uptime')],
 next='IT Service and Support; DDoS and Cyber-Attack Prevention; Privacy Protection Practice.',
 local='Data location and privacy rules differ by place: check where the provider stores data and which law applies.',
 evidence='Your evidence: inventory, option scores, cost table, security checklist, restore test, cut-over and rollback plans, results page.',
 ladder=[('Basics of cloud', 'Explain cloud in plain words. Notes: use a free file service.'), ('Awareness', 'Know models and risks. Notes: compare three real services without naming them.'), ('Foundation', 'Inventory a small setup. Notes: spreadsheet only.'), ('Practitioner', 'Run a small trial move. Notes: practice data only.'), ('Specialist', 'This course. Notes: full plan, cost and rollback.'), ('Advanced', 'Lead multi-system moves. Notes: add governance and automation.'), ('Super expert', 'Set method and teach teachers. Notes: review after each move.')])
